CREATE OR REPLACE FUNCTION public.vehicle_contact_access(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user IS NOT NULL AND public.account_allowed(_user) AND (public.has_role(_user,'admin') OR public.has_paid_bell(_user)) $$;
REVOKE ALL ON FUNCTION public.vehicle_contact_access(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.vehicle_contact_access(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.work_access_internal(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user IS NOT NULL AND public.account_allowed(_user) $$;
CREATE OR REPLACE FUNCTION public.free_work_chat(_other uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND EXISTS(SELECT 1 FROM public.free_work_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) $$;
CREATE OR REPLACE FUNCTION public.consume_directed_bell(_target uuid,_vehicle boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE caller uuid:=auth.uid(); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT public.profile_ready_for_actions(caller) THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; IF _vehicle AND NOT public.vehicle_contact_access(caller) THEN RAISE EXCEPTION 'SUBSCRIPTION_REQUIRED'; END IF; IF caller=_target THEN RETURN; END IF; INSERT INTO public.directed_bell_usage(sender_id,recipient_id) VALUES(caller,_target) ON CONFLICT DO NOTHING; PERFORM 1 FROM public.directed_bell_usage WHERE sender_id=caller AND recipient_id=_target FOR UPDATE; IF EXISTS(SELECT 1 FROM public.directed_bell_usage WHERE sender_id=caller AND recipient_id=_target AND last_rang_at>now()-interval '3 seconds') THEN RETURN; END IF; UPDATE public.directed_bell_usage SET rings=rings+1,last_rang_at=now() WHERE sender_id=caller AND recipient_id=_target; END $$;
DO $$ DECLARE r record; def text; old_guard text:='IF auth.uid() IS NULL OR (NOT public.has_paid_bell(auth.uid()) AND NOT public.has_role(auth.uid(),''admin'')) THEN RAISE EXCEPTION ''SUBSCRIPTION_REQUIRED''; END IF;'; BEGIN FOR r IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('ring_free_work','open_free_work_chat','mark_free_work_category_bell','ring_my_main_bell','request_own_bell_notice','ring_service','request_service','ring_post','open_anonymous_bell_chat') LOOP def:=pg_get_functiondef(r.oid); def:=replace(def,old_guard,'IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION ''SIGN_IN_REQUIRED''; END IF;'); IF r.proname IN ('ring_service','request_service') THEN def:=replace(def,'IF NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION ''PAID_BELL_REQUIRED''; END IF;',''); def:=replace(def,'IF NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION ''PAID_BELL_REQUIRED''; END IF;',''); def:=replace(def,'AND public.has_paid_bell(who.user_id)','AND public.account_allowed(who.user_id)'); END IF; IF r.proname='ring_post' THEN def:=replace(def,'IF public.has_paid_bell(caller) AND NOT EXISTS','IF NOT EXISTS'); END IF; IF r.proname='open_anonymous_bell_chat' THEN def:=replace(def,'IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) OR NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION ''PAID_BELL_REQUIRED''; END IF;','IF (_source=''vehicle'' OR (_source=''post'' AND EXISTS(SELECT 1 FROM public.post_bell_interests b JOIN public.posts p ON p.id=b.post_id WHERE b.id=_id AND p.module=''vehicle''))) AND NOT public.vehicle_contact_access(auth.uid()) THEN RAISE EXCEPTION ''PAID_BELL_REQUIRED''; END IF;'); END IF; EXECUTE def; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND CASE WHEN _other=public.support_admin_id() OR public.has_role(auth.uid(),'admin') THEN true WHEN NOT public.profile_ready_for_actions(auth.uid()) THEN false WHEN public.incoming_bell_reply_allowed(_other,_post) THEN true WHEN _post IS NOT NULL THEN EXISTS(SELECT 1 FROM public.post_chat_pairs c JOIN public.posts p ON p.id=c.post_id WHERE c.post_id=_post AND ((c.member_id=auth.uid() AND c.owner_id=_other) OR (c.owner_id=auth.uid() AND c.member_id=_other)) AND (p.module<>'vehicle' OR public.vehicle_contact_access(auth.uid()))) ELSE public.free_work_chat(_other) OR EXISTS(SELECT 1 FROM public.service_request_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.service_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.bell_board_chat_pairs c WHERE ((c.member_id=auth.uid() AND c.owner_id=_other) OR (c.owner_id=auth.uid() AND c.member_id=_other)) AND (public.vehicle_contact_access(auth.uid()) OR EXISTS(SELECT 1 FROM public.service_requests s WHERE s.id=c.interest_id) OR EXISTS(SELECT 1 FROM public.post_bell_interests b JOIN public.posts p ON p.id=b.post_id WHERE b.id=c.interest_id AND p.module='job'))) OR (public.vehicle_contact_access(auth.uid()) AND EXISTS(SELECT 1 FROM public.vehicle_demand_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.consume_post_slot(uuid,uuid)'::regprocedure) INTO def; def:=replace(def,'cap:=public.subscription_post_limit(_user);','IF public.has_role(_user,''admin'') OR EXISTS(SELECT 1 FROM public.free_work_entries WHERE id=_id AND user_id=_user) OR EXISTS(SELECT 1 FROM public.posts WHERE id=_id AND user_id=_user AND module=''job'') THEN INSERT INTO public.monthly_post_usage(post_id,user_id) VALUES(_id,_user) ON CONFLICT DO NOTHING; RETURN; END IF; cap:=public.subscription_post_limit(_user);'); EXECUTE def; SELECT pg_get_functiondef('public.run_main_bell_batch(uuid)'::regprocedure) INTO def; def:=replace(def,'IF public.has_paid_bell(caller) THEN','IF public.vehicle_contact_access(caller) THEN'); EXECUTE def; END $$;
CREATE OR REPLACE FUNCTION public.guard_post_delay() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.visible_after:=now(); ELSIF NEW.visible_after IS DISTINCT FROM OLD.visible_after AND coalesce(current_setting('app.post_review',true),'')<>'1' THEN RAISE EXCEPTION 'POST_DELAY_PROTECTED'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.get_post_details(_post uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; privileged boolean; contact boolean; BEGIN SELECT * INTO p FROM public.posts WHERE id=_post AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (public.post_listing_visible(posts) AND public.account_allowed(user_id))); IF p.id IS NULL THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; privileged:=p.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'); contact:=privileged OR (auth.uid() IS NOT NULL AND public.my_profile_access_ready() AND p.show_contact AND (p.module<>'vehicle' OR public.vehicle_contact_access(auth.uid()))); RETURN jsonb_build_object('description',p.description,'goods_type',p.goods_type,'capacity_tons',p.capacity_tons,'trip_date',p.trip_date,'created_at',p.created_at,'vehicle_name',p.vehicle_name,'vehicle_number',CASE WHEN contact THEN p.vehicle_number ELSE NULL END,'driver_name',CASE WHEN contact THEN p.driver_name ELSE NULL END,'contact_phone',CASE WHEN contact THEN p.contact_phone ELSE NULL END,'public_brand',CASE WHEN contact THEN p.public_brand ELSE '' END,'public_photo',CASE WHEN contact AND p.public_photo ~ '^https://' THEN p.public_photo ELSE '' END); END $$;
GRANT EXECUTE ON FUNCTION public.get_post_details(uuid) TO anon,authenticated,service_role;
COMMENT ON FUNCTION public.vehicle_contact_access(uuid) IS 'Vehicle-only approved receipt access, with server-validated administrator exemption. Work and service access remains free.';